function countCompleteSubstrings(word, k) {
  const code = (i) => word.charCodeAt(i) - 97;
  const countSegment = (from, to) => {
    let found = 0;
    for (let letters = 1; letters <= 26 && letters * k <= to - from; letters++) {
      const size = letters * k;
      const freq = new Array(26).fill(0);
      let exact = 0;
      for (let right = from; right < to; right++) {
        const add = code(right);
        freq[add]++;
        if (freq[add] === k) exact++;
        else if (freq[add] === k + 1) exact--;
        const left = right - size;
        if (left >= from) {
          const drop = code(left);
          if (freq[drop] === k) exact--;
          else if (freq[drop] === k + 1) exact++;
          freq[drop]--;
        }
        if (right - from + 1 >= size && exact === letters) found++;
      }
    }
    return found;
  };

  let total = 0;
  let segmentStart = 0;
  for (let i = 1; i <= word.length; i++) {
    if (i === word.length || Math.abs(code(i) - code(i - 1)) > 2) {
      total += countSegment(segmentStart, i);
      segmentStart = i;
    }
  }
  return total;
}

