function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(8000, 10000) : int(1, 12);
  const base = int(0, 21);
  const width = int(1, 5);
  const jump = [0, 0.02, 0.1][int(0, 2)];
  let word = '';
  // Short runs of one letter make exact counts more likely.
  while (word.length < n) {
    const letter = rand() < jump ? int(0, 25) : base + int(0, width - 1);
    const run = rand() < 0.5 ? 1 : int(1, 3);
    word += String.fromCharCode(97 + letter).repeat(Math.min(run, n - word.length));
  }
  const k = rand() < 0.85 ? int(1, Math.min(3, n)) : int(1, n);
  return [word, k];
}
